import React, { useState, useEffect, useMemo, useRef, useCallback } from "react";
import { createClient as createSupabaseBrowserClient } from "@supabase/supabase-js";

// Browser-side Supabase client, used ONLY for the OAuth redirect handshake.
// V1 wires up Google only (see signInWithProvider below); the mechanism
// itself is provider-agnostic, so Apple can be added later without
// touching this bridge. Everything else in the app talks to our own /api/*
// backend, which manages its own session cookie — this client's session
// gets bridged into that cookie and then discarded (see the useEffect in
// AppInner that calls /api/auth/oauth-bridge), so there's only ever one
// real source of truth for "who's signed in."
const supabaseBrowser = createSupabaseBrowserClient(
  "https://dixfybqlepticyudikuz.supabase.co",
  "sb_publishable_zOtxwZ1q_OCpiTunktzypw_14pQnQOh"
);

function signInWithProvider(provider) {
  return supabaseBrowser.auth.signInWithOAuth({
    provider,
    options: { redirectTo: window.location.origin },
  });
}

// ---------------------------------------------------------------
// Merveil AI — real call path
// The browser never talks to Anthropic directly (no API key belongs
// in client code). It calls our own serverless endpoint at /api/assistant
// (see /api/assistant.js at the project root), which holds the key
// server-side and forwards the request. Works on Vercel out of the box
// as long as ANTHROPIC_API_KEY is set in the project's env vars.
// ---------------------------------------------------------------
/**
 * Build a language + accent instruction for Merveil AI from the citizen's
 * Passport (languages[], country, city). Speaks their local language when
 * possible, and English with a natural regional flavour (Indian English,
 * French-accented English, African English, Gulf English, etc.).
 */
function merveilVoiceSystem(user, base = "You are Merveil AI, a helpful assistant inside the Merveil super-app for UAE real estate, jobs, networking, and services. Be concise and genuinely useful. Never pretend to be a human.") {
  const langs = (user?.languages || []).map((l) => String(l).trim()).filter(Boolean);
  const country = (user?.country || "").trim();
  const city = (user?.city || "").trim();
  const primary = langs[0] || null;
  const parts = [base];
  if (primary) {
    parts.push(
      `The citizen's Passport primary language is "${primary}". Reply in that language when they write in it or when it is clearly their preferred language. ` +
      `If they write in English, reply in clear English with a natural ${primary}-influenced voice and phrasing (as a fluent local speaker would), not a stiff generic accent.`
    );
  }
  if (langs.length > 1) {
    parts.push(`They also speak: ${langs.slice(1).join(", ")}. You may switch to any of these when they use them.`);
  }
  if (country || city) {
    parts.push(
      `They are associated with ${[city, country].filter(Boolean).join(", ")}. ` +
      `When speaking English, use warm, natural regional English that fits that background (e.g. Indian English for India, Gulf/Emirati-friendly English for UAE, French-influenced English for Francophone Africa or France, West/East African English for those regions) without parody or caricature.`
    );
  }
  parts.push("Match the user's language automatically: if they message in Hindi, reply in Hindi; in French, reply in French; in Arabic, reply in Arabic (Modern Standard or simple Gulf as appropriate); and so on.");
  return parts.join(" ");
}

async function callMerveilAI({ system, messages, maxTokens = 600 }) {
  try {
    const checkRes = await fetch("/api/assistant-usage?action=check", { credentials: "include" });
    if (checkRes.ok) {
      const check = await checkRes.json();
      if (check.allowed === false) {
        const err = new Error(
          `You've reached today's Merveil AI limit (${check.used}/${check.limit} messages) for your ${check.tier === "core" || check.tier === "ordinary" ? "Citizen" : check.tier === "professional" || check.tier === "services" ? "Professional" : check.tier === "company" ? "Company" : "current"} Passport. ` +
          (check.tier !== "investor" ? "Upgrade your Passport for a higher daily limit, or try again tomorrow." : "Try again tomorrow.")
        );
        err.isUsageLimit = true;
        throw err;
      }
    }
  } catch (e) {
    if (e.isUsageLimit) throw e;
    // If the check itself fails (network hiccup, not signed in), don't block
    // the assistant over it — fail open rather than breaking the feature.
  }

  const response = await fetch("/api/assistant", {
    method: "POST",
    credentials: "include",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ system, messages, maxTokens }),
  });
  if (!response.ok) {
    const body = await response.json().catch(() => ({}));
    throw new Error(body.error || `Assistant error (${response.status})`);
  }
  const data = await response.json();
  // Usage is incremented server-side in /api/assistant; client log is optional bookkeeping.
  fetch("/api/assistant-usage?action=log", { method: "POST", credentials: "include" }).catch(() => {});
  return data.reply || "";
}

// Soft session keep: on 401, hit /api/auth/session once then retry the same request.
// Stops false "Please sign in" when the access token just rotated but the citizen is still signed in.
async function merveilFetch(url, options = {}, { retryOn401 = true } = {}) {
  const opts = { credentials: "include", ...options };
  let res = await fetch(url, opts);
  if (retryOn401 && res.status === 401) {
    // Soft restore: rotate cookies, then retry once.
    let restoredUser = null;
    try {
      const sess = await fetch("/api/auth/session", { credentials: "include" });
      if (sess.ok) {
        const body = await sess.json().catch(() => null);
        restoredUser = body?.user || null;
        if (restoredUser?.id) {
          try {
            window.dispatchEvent(new CustomEvent("merveil:session-user", { detail: restoredUser }));
          } catch {}
        }
      }
    } catch { /* ignore */ }
    res = await fetch(url, opts);
    // Still 401 → real session loss (not a refresh race)
    if (res.status === 401 && !restoredUser) {
      try {
        window.dispatchEvent(new CustomEvent("merveil:session-lost"));
      } catch {}
    }
  }
  return res;
}

/** Map Passport tier → server product_id (price is never sent by client). */
function passportProductId(tierId) {
  const t = String(tierId || "").toLowerCase();
  if (t === "professional" || t === "pro" || t === "services") return "passport:professional";
  if (t === "investor") return "passport:investor";
  if (t === "company") return "passport:company";
  return null;
}

/**
 * Poll server payment status. Never trust browser "success".
 * Returns { settled, intent, wallet } or throws.
 */
async function pollPaymentStatus(intentId, { maxAttempts = 24, intervalMs = 1500 } = {}) {
  if (!intentId) throw new Error("Missing payment intent");
  let last = null;
  for (let i = 0; i < maxAttempts; i++) {
    const res = await merveilFetch(
      `/api/wallet?action=payment-status&intentId=${encodeURIComponent(intentId)}`
    );
    const data = await res.json().catch(() => null);
    if (!res.ok) throw new Error(data?.error || "Could not check payment status");
    last = data;
    if (data?.settled) return data;
    const st = data?.intent?.status;
    if (st === "failed" || st === "canceled" || st === "cancelled") {
      throw new Error(data?.intent?.failure_reason || `Payment ${st}`);
    }
    await new Promise((r) => setTimeout(r, intervalMs));
  }
  return last || { settled: false };
}

/**
 * Wallet top-up: server creates intent. Sandbox settles immediately.
 * Stripe returns clientSecret — we do NOT credit locally; poll after confirm.
 * Without Stripe.js loaded, returns mode stripe so UI can show instructions.
 */
async function createWalletTopup(amount, { currency = "AED", idempotencyKey } = {}) {
  const key = idempotencyKey || `topup_${Math.round(Number(amount) * 100)}_${Date.now()}`;
  const res = await merveilFetch("/api/wallet?action=topup", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ amount: Number(amount), currency, purpose: "wallet_topup", idempotencyKey: key }),
  });
  const data = await res.json().catch(() => null);
  if (!res.ok) throw new Error(data?.error || "Top-up failed");
  return data;
}

/**
 * Product checkout (Passport etc.): client sends productId only.
 * Sandbox may settle; Stripe needs clientSecret + webhook.
 */
async function createProductCheckout(productId, { idempotencyKey } = {}) {
  const key = idempotencyKey || `checkout_${productId}_${Date.now()}`;
  const res = await merveilFetch("/api/payments?action=create-checkout", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ productId, idempotencyKey: key }),
  });
  const data = await res.json().catch(() => null);
  if (!res.ok) throw new Error(data?.error || "Checkout failed");
  return data;
}

/**
 * Confirm Stripe PaymentIntent in-browser when Stripe.js is available.
 * Settlement still requires webhook — always poll afterward.
 */
async function confirmStripePayment(clientSecret) {
  if (!clientSecret) return { ok: false, reason: "no_secret" };
  const StripeCtor = typeof window !== "undefined" ? window.Stripe : null;
  const pk = typeof window !== "undefined"
    ? (window.__MERVEIL_STRIPE_PK || window.MERVEIL_STRIPE_PUBLISHABLE_KEY || "")
    : "";
  if (!StripeCtor || !pk) {
    return { ok: false, reason: "stripe_js_missing", message: "Add Stripe.js + publishable key for card confirm. Payment will settle when the webhook fires after you complete payment in Stripe." };
  }
  const stripe = StripeCtor(pk);
  const result = await stripe.confirmPayment({
    clientSecret,
    redirect: "if_required",
    confirmParams: {
      return_url: typeof window !== "undefined" ? `${window.location.origin}/?payment=return` : undefined,
    },
  });
  if (result.error) {
    return { ok: false, reason: "confirm_error", message: result.error.message };
  }
  return { ok: true, paymentIntent: result.paymentIntent };
}

// Real Connect request — pending until the other citizen accepts.
// Returns { status: "pending"|"accepted"|"error", error? }
async function requestMerveilConnection(targetUserId) {
  if (!targetUserId) return { status: "error", error: "No user selected." };
  try {
    const res = await merveilFetch("/api/connections?action=request", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ connectedUserId: targetUserId, userId: targetUserId }),
    });
    const data = await res.json().catch(() => null);
    if (!res.ok) return { status: "error", error: data?.error || `Request failed (${res.status})` };
    // Notify Connect tabs to refresh incoming/accepted lists
    try { window.dispatchEvent(new CustomEvent("merveil:connection-changed", { detail: data })); } catch {}
    return { status: data?.status || "pending", alreadyConnected: !!data?.alreadyConnected, alreadyRequested: !!data?.alreadyRequested };
  } catch (e) {
    return { status: "error", error: e.message || "Network error" };
  }
}

// Relationship between me and another citizen (none | pending | accepted | …).
async function fetchConnectionStatus(otherUserId) {
  if (!otherUserId) return { status: "none", connectionId: null, direction: null };
  try {
    const res = await merveilFetch(`/api/connections?action=status&userId=${encodeURIComponent(otherUserId)}`);
    if (!res.ok) return { status: "none", connectionId: null, direction: null };
    const data = await res.json().catch(() => null);
    return {
      status: data?.status || "none",
      connectionId: data?.connectionId || null,
      direction: data?.direction || null,
    };
  } catch {
    return { status: "none", connectionId: null, direction: null };
  }
}

