/** Normalize any stored tier string → V2 id (keeps old DB values working). */
function normalizePassportId(raw) {
  const id = String(raw || "core").toLowerCase().trim();
  if (id === "ordinary" || id === "citizen" || id === "free") return "core";
  if (id === "services" || id === "service" || id === "pro") return "professional";
  if (id === "professional") return "professional";
  if (id === "investor") return "investor";
  if (id === "company" || id === "org" || id === "organization") return "company";
  return PASSPORT_TIERS[id] ? id : "core";
}

function passportTierOf(user) {
  if (user?.isAdmin) return "investor";
  const raw = user?.passportTier || user?.passport_tier || "core";
  return normalizePassportId(raw);
}

function hasAccess(user, key) {
  if (user?.isAdmin) return true;
  return !!PASSPORT_TIERS[passportTierOf(user)]?.access?.[key];
}

/**
 * Adaptive Passport Algorithm — recommends, never forces.
 * Uses role, profession, activity signals, verification — not a sales ladder.
 */
function recommendPassport(user, statuses = {}) {
  const current = passportTierOf(user);
  const role = String(user?.roleLabel || user?.role_label || "").toLowerCase();
  const profession = String(user?.profession || "").toLowerCase();
  const company = String(user?.companyName || user?.company_name || "").toLowerCase();
  const accountType = String(user?.accountType || user?.account_type || "").toLowerCase();
  const blob = `${role} ${profession} ${company} ${accountType}`;

  const scores = { core: 1, professional: 0, investor: 0, company: 0 };

  if (/agent|broker|consultant|freelance|creator|specialist|sales|provider|entrepreneur|realtor|lawyer|doctor|engineer/.test(blob)) {
    scores.professional += 4;
  }
  if (/invest|capital|fund|portfolio|vc|angel|equity|off-market|deal/.test(blob)) {
    scores.investor += 4;
  }
  if (/company|llc|ltd|corp|organization|agency|group|holding|team/.test(blob) || accountType === "company") {
    scores.company += 4;
  }
  if (hasAccess(user, "postService") || hasAccess(user, "postProperty")) scores.professional += 1;
  if (hasAccess(user, "investorZone")) scores.investor += 2;

  const verifiedCount = Object.values(statuses || {}).filter((s) => s === "verified").length;
  if (verifiedCount >= 2) {
    scores.professional += 0.5;
    scores.investor += 0.5;
  }

  // Don't recommend what they already have as "upgrade" primary
  const ranked = Object.entries(scores)
    .filter(([id]) => id !== "core")
    .sort((a, b) => b[1] - a[1]);
  const top = ranked[0];
  if (!top || top[1] < 2) {
    return { current, recommended: null, reason: null, scores };
  }
  const recId = top[0];
  if (recId === current) {
    return { current, recommended: null, reason: null, scores };
  }
  // Investor already covers most pro tools — don't push professional
  if (current === "investor" && recId === "professional") {
    return { current, recommended: null, reason: null, scores };
  }
  const reasons = {
    professional: "Your activity suggests professional tools may help — list, network, and be discovered as a pro.",
    investor: "Investment-related signals suggest Investor Passport capabilities could fit what you're doing.",
    company: "Organization signals suggest Company Passport for a business presence and team structure.",
  };
  return {
    current,
    recommended: recId,
    reason: reasons[recId] || "This Passport may match your activity.",
    scores,
  };
}

