/** Private Passport Health (not a social score). */
function passportHealthScore(user, statuses = {}, lifeLinks = {}) {
  let score = 35; // base for having an account
  if (user?.name) score += 8;
  if (user?.avatarUrl || user?.avatar_url) score += 8;
  if (user?.bio) score += 6;
  if (user?.profession) score += 5;
  if (user?.city) score += 4;
  if ((user?.languages || []).length) score += 4;
  const verified = Object.values(statuses || {}).filter((s) => s === "verified").length;
  const pending = Object.values(statuses || {}).filter((s) => s === "pending").length;
  score += Math.min(20, verified * 7);
  score += Math.min(6, pending * 2);
  const links = Object.values(lifeLinks || {}).filter((v) => v && (v.url || v.connected));
  score += Math.min(12, links.length * 3);
  return Math.max(0, Math.min(100, Math.round(score)));
}

/**
 * Location-smart pricing — base is USD; display adapts to citizen country/city.
 * Still product-direction prices (from $3 / ~$8 / ~$10), not a hard charge yet.
 */
const PASSPORT_USD = { professional: 3, company: 8, investor: 10 };
const FX_HINT = {
  AE: { code: "AED", rate: 3.67, label: "UAE" },
  SA: { code: "SAR", rate: 3.75, label: "Saudi" },
  QA: { code: "QAR", rate: 3.64, label: "Qatar" },
  KW: { code: "KWD", rate: 0.31, label: "Kuwait" },
  BH: { code: "BHD", rate: 0.38, label: "Bahrain" },
  OM: { code: "OMR", rate: 0.39, label: "Oman" },
  EG: { code: "EGP", rate: 50, label: "Egypt" },
  IN: { code: "INR", rate: 84, label: "India" },
  GB: { code: "GBP", rate: 0.79, label: "UK" },
  EU: { code: "EUR", rate: 0.92, label: "EU" },
  US: { code: "USD", rate: 1, label: "US" },
};
function detectPassportRegion(user) {
  const country = String(user?.country || user?.country_code || "").toUpperCase();
  const city = String(user?.city || "").toLowerCase();
  if (FX_HINT[country]) return country;
  if (/dubai|abu dhabi|sharjah|ajman|uae|emirates/.test(city) || country === "UAE") return "AE";
  if (/riyadh|jeddah|dammam/.test(city)) return "SA";
  if (/london|manchester/.test(city)) return "GB";
  if (/cairo|alexandria/.test(city)) return "EG";
  if (/mumbai|delhi|bangalore|hyderabad/.test(city)) return "IN";
  try {
    const lang = (navigator.language || "").toLowerCase();
    if (lang.includes("ar-ae") || lang.includes("en-ae")) return "AE";
    if (lang.includes("ar-sa")) return "SA";
    if (lang.startsWith("ar")) return "AE";
  } catch {}
  return "US";
}
function formatPassportPrice(user, tierId) {
  const usd = PASSPORT_USD[tierId];
  if (usd == null) return { primary: "Free", secondary: "forever", usd: 0, local: null };
  const region = detectPassportRegion(user);
  const fx = FX_HINT[region] || FX_HINT.US;
  if (fx.code === "USD") {
    return {
      primary: tierId === "professional" ? `From $${usd}` : `Around $${usd}`,
      secondary: "USD · accessible pricing",
      usd,
      local: null,
      region: fx.label,
    };
  }
  const localAmt = Math.round(usd * fx.rate);
  return {
    primary: tierId === "professional" ? `From $${usd}` : `Around $${usd}`,
    secondary: `≈ ${fx.code} ${localAmt} · ${fx.label}`,
    usd,
    local: { code: fx.code, amount: localAmt },
    region: fx.label,
  };
}
function priceLabelForTier(user, tier) {
  if (!tier || tier.id === "core") return { price: "Free", priceNote: " forever" };
  const p = formatPassportPrice(user, tier.id);
  return { price: p.primary, priceNote: p.secondary ? ` · ${p.secondary}` : "" };
}

