/** In-call / incoming ring tone (Web Audio). No external assets — works offline. */
const CallRingtone = (() => {
  let ctx = null, timer = null, playing = false, unlocked = false;
  function ensure() {
    if (ctx) return ctx;
    try {
      const AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return null;
      ctx = new AC();
    } catch { return null; }
    return ctx;
  }
  /** Call once from any user gesture so mobile browsers allow sound later. */
  function unlock() {
    if (unlocked) return;
    unlocked = true;
    const c = ensure();
    if (!c) return;
    try {
      if (c.state === "suspended") c.resume();
      // silent buffer kick
      const buf = c.createBuffer(1, 1, 22050);
      const src = c.createBufferSource();
      src.buffer = buf;
      src.connect(c.destination);
      src.start(0);
    } catch {}
  }
  // Unlock on first touch/click anywhere
  if (typeof window !== "undefined") {
    const once = () => { unlock(); window.removeEventListener("pointerdown", once); window.removeEventListener("touchstart", once); window.removeEventListener("click", once); };
    window.addEventListener("pointerdown", once, { once: true, passive: true });
    window.addEventListener("touchstart", once, { once: true, passive: true });
    window.addEventListener("click", once, { once: true });
  }
  function beep(c, t0, freq, dur, gain) {
    try {
      const o = c.createOscillator();
      const g = c.createGain();
      o.type = "sine";
      o.frequency.setValueAtTime(freq, t0);
      g.gain.setValueAtTime(0.0001, t0);
      g.gain.exponentialRampToValueAtTime(Math.max(0.001, gain), t0 + 0.02);
      g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
      o.connect(g); g.connect(c.destination);
      o.start(t0); o.stop(t0 + dur + 0.05);
    } catch {}
  }
  function pulse() {
    const c = ensure();
    if (!c || !playing) return;
    if (c.state === "suspended") { try { c.resume(); } catch {} }
    const t = c.currentTime;
    // Louder dual-tone ring
    beep(c, t, 440, 0.22, 0.35);
    beep(c, t + 0.22, 520, 0.22, 0.32);
    beep(c, t + 0.5, 440, 0.22, 0.35);
    beep(c, t + 0.72, 520, 0.22, 0.32);
  }
  return {
    unlock,
    start() {
      unlock();
      if (playing) return;
      playing = true;
      const c = ensure();
      if (c && c.state === "suspended") { try { c.resume(); } catch {} }
      pulse();
      timer = setInterval(pulse, 2000);
      try { if (navigator.vibrate) navigator.vibrate([250, 120, 250, 120, 250]); } catch {}
    },
    stop() {
      playing = false;
      if (timer) { clearInterval(timer); timer = null; }
      try { if (navigator.vibrate) navigator.vibrate(0); } catch {}
    },
  };
})();

// Professional Passport progressive completion (0–100%) — separate from
// and additive to the paid tier system above (PASSPORT_TIERS/hasAccess
// gates monetized features; this gates basic social participation based
// on how filled-out the profile is, per the Merveil AI spec:
//   20%  → account exists: browse, search, watch, follow, save
//   40%  → comment, reply, connect, post, list, apply, World (new-user friendly)
//   100% → fully complete profile (+ manual verification for the badge)
/** Profile completion 0–100%. Accepts camelCase (app) or snake_case (API). */
function passportCompletionOf(user) {
  if (!user) return 0;
  if (user.isAdmin || user.is_admin) return 100;
  const avatar = user.avatarUrl || user.avatar_url;
  const bio = (user.bio || "").trim();
  const city = user.city;
  const profession = user.profession;
  const skills = user.skills || [];
  const languages = user.languages || [];
  const portfolio = user.portfolioUrl || user.portfolio_url || user.websiteUrl || user.website_url;
  let pct = 20; // signed-in account
  if (avatar) pct += 15;
  if (bio.length > 10) pct += 15;
  if (city) pct += 10;
  if (profession) pct += 10;
  if (Array.isArray(skills) && skills.length > 0) pct += 10;
  if (Array.isArray(languages) && languages.length > 0) pct += 10;
  if (portfolio) pct += 10;
  return Math.min(100, pct);
}

/**
 * Android system back / browser back for overlays (reels, modals, tabs).
 * pushLayer(id) when opening; popLayer() or hardware back closes top layer.
 */
function useBackStack() {
  const stackRef = useRef([]);
  const handlersRef = useRef(new Map());

  const pushLayer = useCallback((id, onBack) => {
    if (!id) return;
    handlersRef.current.set(id, onBack);
    // Avoid duplicate consecutive entries for the same layer
    const top = stackRef.current[stackRef.current.length - 1];
    if (top === id) return;
    stackRef.current.push(id);
    try {
      history.pushState({ merveilBack: id, ts: Date.now() }, "", window.location.href);
    } catch {}
  }, []);

  const popLayer = useCallback((id) => {
    if (id) {
      handlersRef.current.delete(id);
      stackRef.current = stackRef.current.filter((x) => x !== id);
      return;
    }
    const top = stackRef.current.pop();
    if (top) handlersRef.current.delete(top);
  }, []);

  useEffect(() => {
    const onPop = () => {
      const top = stackRef.current.pop();
      if (!top) return;
      const fn = handlersRef.current.get(top);
      handlersRef.current.delete(top);
      try { fn?.(); } catch {}
    };
    window.addEventListener("popstate", onPop);
    return () => window.removeEventListener("popstate", onPop);
  }, []);

  // Stable identity so effects that depend on this API don't re-run every render
  return useMemo(() => ({ pushLayer, popLayer }), [pushLayer, popLayer]);
}

const BackStackContext = React.createContext({ pushLayer: () => {}, popLayer: () => {} });
function useAppBack() {
  return React.useContext(BackStackContext);
}
function passportAccessLevel(user) {
  const pct = passportCompletionOf(user);
  if (pct >= 100) return "full";
  if (pct >= 40) return "create";
  if (pct >= 20) return "engage";
  return "browse";
}
function canEngage(user) { return passportCompletionOf(user) >= 40; } // comment, reply, connect
function canCreate(user) { return passportCompletionOf(user) >= 40; } // post, list, apply, World

